require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='schedules';$pageTitle='Stipend Schedules';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];if(fo_has_table($conn,'stipend_schedules')){$s=$conn->prepare("SELECT * FROM stipend_schedules WHERE created_by=? ORDER BY created_at DESC");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?>
